using System;using System.Collections.Generic;using System.Linq;using InterchangeBuilder.LaneConnections;
public static class SpatialChecks{
public static readonly List<object> Evidence=new List<object>();
public static List<object> Run(){Evidence.Clear();var rows=new List<object>();void Check(string name,bool value){rows.Add(new{name,expected=true,actual=value});if(!value)throw new Exception(name);}
var lower=SpatialEnvelopeProof.Straight("lower",new CurvePoint(-100,0),new CurvePoint(100,0),8,0,2);
var high=SpatialEnvelopeProof.Straight("upper",new CurvePoint(0,-100),new CurvePoint(0,100),8,12,2);
Check("full width underside clearance10",SpatialEnvelopeProof.Compare(lower,high,9).Status==SpatialProofStatus.Separated);
Check("clearance equality unknown",SpatialEnvelopeProof.Compare(lower,high,10).Status==SpatialProofStatus.Unknown);
var thick=SpatialEnvelopeProof.Straight("upper",new CurvePoint(0,-100),new CurvePoint(0,100),8,12,13);
Check("increasing thickness actual overlap",SpatialEnvelopeProof.Compare(lower,thick,0).Status==SpatialProofStatus.OverlapWitness);
var uncertain=new SpatialEnvelope("curve",-10,10,-10,10,-1,1);
Check("outer box overlap never geometry proof",SpatialEnvelopeProof.Compare(lower,uncertain,0).Status==SpatialProofStatus.Unknown);
var dir=new CurvePoint(1,0);var request=new CurveKernelRequest(new CurvePort("a",new CurvePoint(0,0),dir,0,0,8,CurveTravelSide.Middle),new CurvePort("b",new CurvePoint(200,0),dir,0,0,8,CurveTravelSide.Middle),40,8,true,1);
var route=new CurveGeometryDocument(request,8,new[]{new CurveGeometrySegment(CurveSegmentKind.Line,new[]{new CurvePoint(0,0),new CurvePoint(160,0)}),new CurveGeometrySegment(CurveSegmentKind.Line,new[]{new CurvePoint(160,0),new CurvePoint(200,0)})});
Check("entire straight route exact split proof",SpatialEnvelopeProof.EntireSingleStraight(route,12,2).Status==SpatialProofStatus.Separated);
var candidate=ExperimentalCurveKernel.Generate(request,true);var c=candidate.Candidates[1];var bezier=new CurveGeometryDocument(request,8,new[]{new CurveGeometrySegment(CurveSegmentKind.Bezier,c.Controls),new CurveGeometrySegment(CurveSegmentKind.Line,new[]{c.TailStart,c.TailEnd})});
Check("unproved curve global domain never verified",SpatialEnvelopeProof.EntireSingleStraight(bezier,12,2).Status==SpatialProofStatus.Unknown);
Check("tiny thickness cannot certify collapsed prism",SpatialEnvelopeProof.EntireSingleStraight(route,10000,1e-14).Status==SpatialProofStatus.InvalidInput);
Check("no placement permission",!SpatialEnvelopeProof.Compare(lower,high,9).CanApplyToGame);var low=new QuarterArcCandidate(50,8,40,0,0,0,2,1);var highArc=new QuarterArcCandidate(50,8,40,12,12,12,2,1);
Check("nonstraight whole arc tail domain certified",QuarterArcSpatialProof.Verify(low,1,.1).Status==SpatialProofStatus.Separated);
Check("curved full width crossing separation",QuarterArcSpatialProof.Compare(low,1,highArc,1,.1,9).Status==SpatialProofStatus.Separated);
var lowArc=new QuarterArcCandidate(50,8,40,1,1,1,2,1);
Check("curved actual overlap witness",QuarterArcSpatialProof.Compare(low,1,lowArc,1,.1,0).Status==SpatialProofStatus.OverlapWitness);
Check("arc straight strict G2 not silently passed",QuarterArcSpatialProof.Verify(low,1,.1,true).Status==SpatialProofStatus.Unknown);
Check("same segment radial fold unknown",QuarterArcSpatialProof.Verify(new QuarterArcCandidate(3,8,40,0,0,0,2,1),1,.1).Status==SpatialProofStatus.Unknown);
Check("stale exact candidate rejected",QuarterArcSpatialProof.Verify(low,2,.1).Status==SpatialProofStatus.InvalidInput);
Check("actual candidate selection rejects colliding then chooses high",QuarterArcSpatialProof.Select(new[]{lowArc,highArc},new[]{low},1,.1,9)==1);
Check("no collision cannot bypass proof",QuarterArcSpatialProof.Select(new[]{lowArc},new[]{low},1,.1,0,mode:CurvePlacementMode.NoCollision)==-1);
double arcL=50*Math.PI/2;var slope=new QuarterArcCandidate(50,8,40,0,arcL*.05,arcL*.05+2,2,1);
Check("curved station linear profile exact grade",Math.Abs(QuarterArcSpatialProof.Verify(slope,1,.08).MaximumGrade-(.05*50/46))<1e-12&&QuarterArcSpatialProof.Verify(slope,1,.08).Status==SpatialProofStatus.Unknown);
Check("vertical seam mismatch unknown",QuarterArcSpatialProof.Verify(new QuarterArcCandidate(50,8,40,0,5,5,2,1),1,.1).Status==SpatialProofStatus.Unknown);
var arcRequest=new CurveKernelRequest(new CurvePort("arc-start",new CurvePoint(50,0),new CurvePoint(0,1),.02,0,8,CurveTravelSide.Middle),new CurvePort("tail-end",new CurvePoint(-40,50),new CurvePoint(-1,0),0,0,8,CurveTravelSide.Middle),40,8,false,1);
Check("selected ports and actual arc candidate integrated",QuarterArcSpatialProof.SelectForRequest(arcRequest,new[]{lowArc,highArc},new[]{low},.1,9)==1);
Check("width changed cannot reuse candidate",QuarterArcSpatialProof.SelectForRequest(new CurveKernelRequest(arcRequest.Start,arcRequest.End,40,9,false,1),new[]{highArc},new[]{low},.1,9)==-1);
Check("folded Bezier whole domain remains unknown",SpatialEnvelopeProof.EntireSingleStraight(new CurveGeometryDocument(request,8,new[]{new CurveGeometrySegment(CurveSegmentKind.Bezier,new[]{new CurvePoint(0,0),new CurvePoint(200,100),new CurvePoint(-100,100),new CurvePoint(200,0)})}),0,2).Status!=SpatialProofStatus.Separated);
Check("invalid crossing clearance preserved",QuarterArcSpatialProof.Compare(low,1,lowArc,1,.1,double.NaN).Status==SpatialProofStatus.InvalidInput);
Check("underflow grade cannot certify nonconstant surface",QuarterArcSpatialProof.Verify(new QuarterArcCandidate(50,8,40,0,double.Epsilon,double.Epsilon,2,1),1,.1).Status==SpatialProofStatus.Unknown);
var curveRequest=new CurveKernelRequest(new CurvePort("s",new CurvePoint(0,0),new CurvePoint(1,0),0,0,8,CurveTravelSide.Middle),new CurvePort("e",new CurvePoint(300,60),new CurvePoint(1,0),0,0,8,CurveTravelSide.Middle),40,8,true,1);
var output=ExperimentalCurveKernel.Generate(curveRequest,true).Candidates[1];var actual=new CurveGeometryDocument(curveRequest,8,new[]{new CurveGeometrySegment(CurveSegmentKind.Bezier,output.Controls),new CurveGeometrySegment(CurveSegmentKind.Line,new[]{output.TailStart,output.TailEnd})});
var crossings=new[]{SpatialEnvelopeProof.Straight("road1",new CurvePoint(100,-100),new CurvePoint(100,150),8,0,2),SpatialEnvelopeProof.Straight("road2",new CurvePoint(200,-100),new CurvePoint(200,150),8,0,2)};
var external=BezierExternalSpatialProof.Verify(curveRequest,actual,crossings,0,.1,2,6);
Check("rising curved two-crossing continuous external certificate",external.Status==SpatialProofStatus.Separated&&external.Pairs==external.Leaves.Count*2&&external.SeparatedPairs==external.Pairs);
Check("external certificate never implies self or apply",external.GlobalSelfStatus==SpatialProofStatus.Unknown&&!external.CanApplyToGame);
Check("lower rising curve cannot pass",BezierExternalSpatialProof.Verify(curveRequest,actual,crossings,0,.002,2,9).Status==SpatialProofStatus.Unknown);
Check("thicker structure cannot pass",BezierExternalSpatialProof.Verify(curveRequest,actual,crossings,12,.02,15,9).Status==SpatialProofStatus.Unknown);
Check("coverage budget exhaustion fails closed",BezierExternalSpatialProof.Verify(curveRequest,actual,crossings,12,.02,2,9,8,2).Status==SpatialProofStatus.Unknown);
var parallel=new[]{SpatialEnvelopeProof.Straight("parallel",new CurvePoint(0,10),new CurvePoint(300,10),20,0,2)};
Check("long overlap low end never certified",BezierExternalSpatialProof.Verify(curveRequest,actual,parallel,0,.1,2,9).Status==SpatialProofStatus.Unknown);
Check("descending curved enclosure conservatively separated",BezierExternalSpatialProof.Verify(curveRequest,actual,crossings,30,-.02,2,9).Status==SpatialProofStatus.Separated);
Evidence.Add(new{request=curveRequest,actualGeometry=actual,obstacles=crossings,certificate=external,scope="external separation only; global self UNKNOWN; no placement"});
Check("descending low endpoint overlap stays unknown",BezierExternalSpatialProof.Verify(curveRequest,actual,new[]{SpatialEnvelopeProof.Straight("end-parallel",new CurvePoint(0,60),new CurvePoint(300,60),20,0,2)},30,-.1,2,9).Status==SpatialProofStatus.Unknown);
var self=NormalStripSelfProof.Verify(curveRequest,actual);
Check("noncircular Bezier normal strip global injection",self.Status==SpatialProofStatus.Separated);
var c0=output.Controls;var work=c0.ToArray();var leftControls=new CurvePoint[work.Length];var rightControls=new CurvePoint[work.Length];leftControls[0]=work[0];rightControls[work.Length-1]=work[work.Length-1];for(int k=work.Length-1;k>0;k--){for(int j=0;j<k;j++)work[j]=(work[j]+work[j+1])*.5;leftControls[work.Length-k]=work[0];rightControls[k-1]=work[k-1];}
var split=new CurveGeometryDocument(curveRequest,8,new[]{new CurveGeometrySegment(CurveSegmentKind.Bezier,leftControls),new CurveGeometrySegment(CurveSegmentKind.Bezier,rightControls),new CurveGeometrySegment(CurveSegmentKind.Line,new[]{output.TailStart,output.TailEnd})});
Check("exact split preserves noncircle self certificate",NormalStripSelfProof.Verify(curveRequest,split).Status==SpatialProofStatus.Separated);
Check("folded route never globally certified",NormalStripSelfProof.Verify(request,new CurveGeometryDocument(request,8,new[]{new CurveGeometrySegment(CurveSegmentKind.Bezier,new[]{new CurvePoint(0,0),new CurvePoint(200,100),new CurvePoint(-100,100),new CurvePoint(200,0)})})).Status!=SpatialProofStatus.Separated);
Evidence.Add(new{selfRequest=curveRequest,actualNormalStrip=actual,globalSelfCertificate=self,splitCertificate=NormalStripSelfProof.Verify(curveRequest,split)});
var reverseParts=new CurveGeometryDocument(request,8,new[]{new CurveGeometrySegment(CurveSegmentKind.Line,new[]{new CurvePoint(0,0),new CurvePoint(100,0)}),new CurveGeometrySegment(CurveSegmentKind.Line,new[]{new CurvePoint(100,0),new CurvePoint(0,0)}),new CurveGeometrySegment(CurveSegmentKind.Line,new[]{new CurvePoint(0,0),new CurvePoint(200,0)})});
Check("adjacent reverse cannot globally certify",NormalStripSelfProof.Verify(request,reverseParts).Status==SpatialProofStatus.Unknown);
var wideRequest=new CurveKernelRequest(new CurvePort("w0",new CurvePoint(0,0),new CurvePoint(1,0),0,0,50,CurveTravelSide.Middle),new CurvePort("w1",new CurvePoint(60,30),new CurvePoint(1,0),0,0,50,CurveTravelSide.Middle),10,50,true,1);
var wide=ExperimentalCurveKernel.Generate(wideRequest,true).Candidates[1];var wideGeometry=new CurveGeometryDocument(wideRequest,50,new[]{new CurveGeometrySegment(CurveSegmentKind.Bezier,wide.Controls),new CurveGeometrySegment(CurveSegmentKind.Line,new[]{wide.TailStart,wide.TailEnd})});
Check("too wide tight shift stays unknown",NormalStripSelfProof.Verify(wideRequest,wideGeometry).Status==SpatialProofStatus.Unknown);
double delta=1e-8;var tinyDirection=new CurvePoint(Math.Cos(delta),Math.Sin(delta));var cornerEnd=tinyDirection*100;
var tinyRequest=new CurveKernelRequest(new CurvePort("j0",new CurvePoint(-100,0),new CurvePoint(1,0),0,0,8,CurveTravelSide.Middle),new CurvePort("j1",cornerEnd,tinyDirection,0,0,8,CurveTravelSide.Middle),40,8,true,1);
var tinyCorner=new CurveGeometryDocument(tinyRequest,8,new[]{new CurveGeometrySegment(CurveSegmentKind.Line,new[]{new CurvePoint(-100,0),new CurvePoint(0,0)}),new CurveGeometrySegment(CurveSegmentKind.Line,new[]{new CurvePoint(0,0),cornerEnd})});
Check("tiny tangent jump cannot use global theorem",NormalStripSelfProof.Verify(tinyRequest,tinyCorner).Status==SpatialProofStatus.Unknown);
var tinyGap=new CurveGeometryDocument(request,8,new[]{new CurveGeometrySegment(CurveSegmentKind.Line,new[]{new CurvePoint(0,0),new CurvePoint(100,0)}),new CurveGeometrySegment(CurveSegmentKind.Line,new[]{new CurvePoint(100-5e-8,0),new CurvePoint(200,0)})});
Check("tiny overlapping G0 seam cannot certify",NormalStripSelfProof.Verify(request,tinyGap).Status==SpatialProofStatus.Unknown);
Check("candidate search binds self certificate to actual output",CurveCandidateSearch.Search(curveRequest,true).Candidates[1].SelfCertificate.Status==SpatialProofStatus.Separated);
return rows;}}
